class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        dict1 = {}
        dict2 = {}

        for coord in coordinates:
            i, j = coord[0], coord[1]
            x_start = i - 1
            x_end = i + 1
            y_start = j - 1
            y_end = j + 1

            for x in range(x_start, x_end + 1):
                for y in range(y_start, y_end + 1):
                    if 0 <= x < m - 1 and 0 <= y < n - 1:
                        dict1[(x, y)] = dict1.get((x, y), 0) + 1

        from collections import Counter
        dict2 = Counter(dict1.values())

        total_blocks = (m - 1) * (n - 1)
        filled_blocks = sum(dict2.values())

        return [total_blocks - filled_blocks, dict2.get(1, 0), dict2.get(2, 0), dict2.get(3, 0), dict2.get(4, 0)]
